let stGen = 0;
const NIGHT_LEN = 180, NIGHT_OUT = 0.96, NIGHT_IN = NIGHT_OUT - NIGHT_LEN / DAY_LEN, DUSK = 21.6 / DAY_LEN;   // dusk as long as it was, in seconds
